# ! [doc = " Check if it's even possible to satisfy the 'where' clauses"] # ! [doc = " for this item."] # ! [doc = ""] # ! [doc = " It's possible to `#!feature(trivial_bounds)]` to write"] # ! [doc = " a function with impossible to satisfy clauses, e.g.:"] # ! [doc = " `fn foo() where String: Copy {}`."] # ! [doc = ""] # ! [doc = " We don't usually need to worry about this kind of case,"] # ! [doc = " since we would get a compilation error if the user tried"] # ! [doc = " to call it. However, since we optimize even without any"] # ! [doc = " calls to the function, we need to make sure that it even"] # ! [doc = " makes sense to try to evaluate the body."] # ! [doc = ""] # ! [doc = " If there are unsatisfiable where clauses, then all bets are"] # ! [doc = " off, and we just give up."] # ! [doc = ""] # ! [doc = " We manually filter the predicates, skipping anything that's not"] # ! [doc = " \"global\". We are in a potentially generic context"] # ! [doc = " (e.g. we are evaluating a function without instantiating generic"] # ! [doc = " parameters, so this filtering serves two purposes:"] # ! [doc = ""] # ! [doc = " 1. We skip evaluating any predicates that we would"] # ! [doc = " never be able prove are unsatisfiable (e.g. `<T as Foo>`"] # ! [doc = " 2. We avoid trying to normalize predicates involving generic"] # ! [doc = " parameters (e.g. `<T as Foo>::MyItem`). This can confuse"] # ! [doc = " the normalization code (leading to cycle errors), since"] # ! [doc = " it's usually never invoked in this way."] use split_decls_genesis :: ourprelude :: * ; use rustc_middle :: mir :: { Body , START_BLOCK , TerminatorKind } ; use rustc_middle :: ty :: { TyCtxt , TypeFlags , TypeVisitableExt } ; use rustc_trait_selection :: traits ; use tracing :: trace ; use crate :: pass_manager :: MirPass ; pub (crate) struct ImpossiblePredicates ; impl < 'tcx > MirPass < 'tcx > for ImpossiblePredicates { #[tracing :: instrument (level = "trace" , skip (self , tcx , body))] fn run_pass (& self , tcx : TyCtxt < 'tcx > , body : & mut Body < 'tcx >) { tracing :: trace ! (def_id = ? body . source . def_id ()) ; let predicates = tcx . predicates_of (body . source . def_id ()) . instantiate_identity (tcx) ; tracing :: trace ! (? predicates) ; let predicates = predicates . predicates . into_iter () . filter (| p | { ! p . has_type_flags (TypeFlags :: HAS_FREE_LOCAL_NAMES | TypeFlags :: HAS_CT_PROJECTION ,) }) ; let predicates : Vec < _ > = traits :: elaborate (tcx , predicates) . collect () ; tracing :: trace ! (? predicates) ; if predicates . references_error () || traits :: impossible_predicates (tcx , predicates) { trace ! ("found unsatisfiable predicates") ; let bbs = body . basic_blocks . as_mut () ; bbs . raw . truncate (1) ; bbs [START_BLOCK] . statements . clear () ; bbs [START_BLOCK] . terminator_mut () . kind = TerminatorKind :: Unreachable ; body . var_debug_info . clear () ; body . local_decls . raw . truncate (body . arg_count + 1) ; } } fn is_required (& self) -> bool { true } }